function eb.weatherStrength(Pn)
local Qn=eb.fx(Pn)
local Rn=Qn.dmg/Qn.cd/Qn.hp/Qn.speed*(1+(Qn.range-1)/2)
for Sn,Tn in pairs(Qn.kinds)do
Rn=Rn*(1+Q.rogueShare(Sn)*Tn)
end
if Qn.ice>0 then
local Un=Q.rogueShare(Dxc[1668])
Rn=Rn*(Un+(1-Un)/(1-Qn.ice+Qn.ice/W.modFactor(Dxc[1718])))
end
if Qn.fly>0 then
Rn=Rn*(1-Qn.fly*0.5)
end
if Qn.noCC then
Rn=Rn*0.95
end
if Qn.shroud then
Rn=Rn*0.9
end
return Rn
end
function eb.cardGems(Vn,Wn)
local Xn=0
local Yn=eb.pearlsFrom(Wn+1,50)
for Zn,ao in pairs(type(Vn.effects)==Dxc[1489]and Vn.effects or{})do
if type(ao)==Dxc[1489]then
local bo=tonumber(ao.amount)or 0
if ao.type==Dxc[1719]then
Xn=Xn+math.abs(bo)*Yn*I.pearlValue
elseif ao.type==Dxc[1720]then
local co,eo=pcall(O.rewardValue,ao.reward)
if co then
Xn=Xn+(tonumber(eo)or 0)
end
elseif ao.type==Dxc[1721]then
Xn=Xn+bo*eb.STARFALL_GEMS
elseif ao.type==Dxc[1722]then
Xn=Xn+bo*100
end
end
end
if Vn.option_type==Dxc[1723]then
Xn=Xn+eb.HARD_GEMS
end
if Vn.weather then
local fo=Vn.weather~=eb.weatherNow()
if fo and Vn.weather==Dxc[1671]then
Xn=Xn+eb.STARFALL_GEMS
end
local go=eb.board()
if fo and go and Vn.weather~=Dxc[1677]and not go.weathers[Vn.weather]then
Xn=Xn+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
end
end
return Xn
end
