function db.gainXp(rK,sK)
local tK,uK=tonumber(rK.xp)or 0,db.xpFor(rK.unit_id,db.cap(rK))
local vK=math.max(0,uK-tK)
if vK<=0 or(sK or 0)<=0 then
return 0,0
end
local wK=math.min(sK,vK)
local xK=db.base(rK)
if xK<=0 then
return 0,wK
end
return db.share(rK.unit_id)*(db.score(db.whatIf(rK,{xp=tK+wK}))/xK-1)*100,wK
end
function db.gainFuse(yK)
if db.lb(yK)>=1 then
return 0
end
local zK=db.base(yK)
if zK<=0 then
return 0
end
local AK=db.whatIf(yK,{xp=math.max(tonumber(yK.xp)or 0,db.xpFor(yK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(yK.unit_id)*(db.score(AK)/zK-1)*100+5
end
