function db.relicWorth(BK,CK)
local DK=CK._unique_item_data and CK._unique_item_data._unique_relic_data
if not DK then
return 0
end
local EK=H.Items[CK.item_id]or{}
local FK,GK=N.types(BK.unit_id)
if EK.main_damage_type and EK.main_damage_type~=Dxc[2109]and EK.main_damage_type~=GK then
return 0
end
local HK,IK=0,0
for JK,KK in pairs(DK._core_damage_type_buffs or{})do
if FK[KK.damage_type]then
HK=HK+(tonumber(KK.mul)or 0)+(tonumber(KK.add_upg)or 0)*0.01+(tonumber(KK.pen)or 0)*0.001
IK=IK+(tonumber(KK.crit)or 0)
end
end
HK=HK+IK*0.5
local LK=N.rows(BK.unit_id)
local MK=LK and LK[LK.max]
local NK=(MK and tonumber(MK.cd)or 0)*N.mult(BK,Dxc[1624])
for OK,PK in pairs(DK._unique_relic_effects or{})do
local QK=type(PK.params)==Dxc[1489]and PK.params or{}
if PK.id==Dxc[2110]then
local RK=math.min(1,(tonumber(QK.extra_damage)or 0)*NK/math.max(1,tonumber(QK.time_interval)or 40))
local SK=N.DRONES and N.DRONES[BK.unit_id]
if SK and SK.late and NK>0 then
local TK=1/NK
RK=RK*TK/(TK+(tonumber(SK.max)or 0)*(tonumber(SK.late.dmg)or 0)*(tonumber(SK.hits)or 1)/math.max(0.1,tonumber(SK.late.cd)or 4))
end
HK=HK+RK
elseif PK.id==Dxc[2111]then
HK=HK+(tonumber(QK.dmg_buff)or 0)*0.25
elseif PK.id==Dxc[2112]then
HK=HK+(tonumber(QK.dmg_buff)or 0)*IK
elseif PK.id==Dxc[2113]then
if FK.magic then
HK=0
else
HK=HK+(tonumber(QK.dmg_buff)or 0)*0.3
end
elseif PK.id==Dxc[2114]then
if FK.water_damage then
HK=HK+0.05
end
end
end
return HK
end
function db.relicPlan()
