local gL=db.relicWorth(aL.u,fL)*cL*100
if gL>0.01 then
table.insert(dL,{it=fL,w=gL})
end
end
table.sort(dL,function(hL,iL)
if hL.w~=iL.w then
return hL.w>iL.w
end
return hL.it.uuid<iL.it.uuid
end)
local jL,kL={},{}
for lL,mL in ipairs(dL)do
local nL=kL[mL.it.item_id]or 0
if#jL<6 and nL<((H.Items[mL.it.item_id]or{}).unique_equip and 1 or 2)then
kL[mL.it.item_id]=nL+1
table.insert(jL,mL)
end
end
if aL.u._equipped_relic then
local oL=false
for pL,qL in ipairs(jL)do
if qL.it.uuid==aL.u._equipped_relic then
oL=true
end
end
local rL=not oL and UK.inventory:get_item_by_uuid(aL.u._equipped_relic)
if rL then
table.insert(jL,{it=rL,w=db.relicWorth(aL.u,rL)*cL*100})
