for MQ,NQ in ipairs(J.goals or{})do
EQ[NQ.uuid]=true
for OQ,PQ in ipairs(NQ.eats or{})do
FQ[PQ.id]=true
end
end
for QQ,RQ in ipairs(J.str and J.str.core or{})do
EQ[RQ]=true
end
local SQ=ab.strongest(10)
local TQ,UQ={},0
for VQ,WQ in pairs(DQ.profile_data.collection.owned_units)do
local XQ=DQ.collection:get_unit_by_uuid(VQ)or WQ
local YQ,ZQ,_Q=pcall(H.USC.is_unit_good_for_fusion,BQ,XQ)
if YQ and ZQ and not(WQ._locked or XQ._locked)and not EQ[VQ]and not FQ[XQ.unit_id]and not(WQ._equipped_relic or XQ._equipped_relic)and not(WQ.shiny or XQ.shiny)and not N.trait(XQ)and not(WQ.further_modifiers and WQ.further_modifiers.limit_break)then
local aR=ab.fodderOrder(XQ.unit_id)
if aR and not SQ[VQ]then
local bR,cR=pcall(N.score,XQ)
table.insert(TQ,{uuid=VQ,id=XQ.unit_id,pts=tonumber(_Q)or 1,sc=bR and cR or 0,order=aR})
UQ=UQ+(tonumber(_Q)or 1)
end
end
end
table.sort(TQ,function(dR,eR)
if dR.order~=eR.order then
return dR.order<eR.order
end
if dR.sc~=eR.sc then
return dR.sc<eR.sc
end
return dR.uuid<eR.uuid
end)
local fR,gR={},0
for hR,iR in ipairs(TQ)do
