end
local CR={}
for DR,ER in pairs(kR.profile_data.collection.owned_units)do
if DR~=jR.uuid and not lR[DR]and not ER._locked then
local FR=kR.collection:get_unit_by_uuid(DR)or ER
local GR,HR,IR=pcall(H.USC.is_unit_good_for_fusion,jR,FR)
