local NR,OR=pcall(N.score,FR)
table.insert(CR,{uuid=DR,id=FR.unit_id,name=N.name(FR.unit_id),rarity=JR.rarity or Dxc[1726],lvl=db.level(FR),pts=tonumber(IR)or 1,evolved=N.isEvolvedForm(FR.unit_id),flags=KR,safe=xR[DR]or false,sc=NR and OR or 0})
end
