end
if#uT==0 then
P.pickNote.autoFuseXp=Dxc[2241]
return
end
if os.time()-(tonumber(I.fuseXpOnAt)or 0)<30 then
P.pickNote.autoFuseXp=Dxc[2242]
return
end
P.pickNote.autoFuseXp=nil
if j.req.back.fuseXp and M.now()<j.req.back.fuseXp then
return
end
P.fuseBatch=P.fuseBatch or 50
local xT,yT,zT=0,0,{}
while j.alive and xT<10 do
if xT>0 then
local AT,BT,CT=P.xpFodder(rT.collection:get_unit_by_uuid(I.fuseXpUnit)or sT)
uT,wT={},CT
for ET,FT in ipairs(AT)do
if not zT[FT.uuid]then
table.insert(uT,FT)
end
end
if wT<=0 or#uT==0 then
break
end
end
local GT={}
for HT=1,math.min(P.fuseBatch,#uT)do
table.insert(GT,uT[HT].uuid)
end
local IT=tonumber((rT.collection:get_unit_by_uuid(I.fuseXpUnit)or sT).xp)or 0
local JT=M.now()
