end
yT=yT+1
task.wait(3.5)
continue
end
while M.now()-JT<5 and(tonumber((rT.collection:get_unit_by_uuid(I.fuseXpUnit)or sT).xp)or 0)<=IT do
task.wait(0.1)
end
local NT=tonumber((rT.collection:get_unit_by_uuid(I.fuseXpUnit)or sT).xp)or 0
if NT>IT then
xT=xT+1
for OT,PT in ipairs(GT)do
zT[PT]=true
end
R.add(string.format(Dxc[2245],#GT,tT),#GT,Dxc[2246],string.format(Dxc[2247],M.fmt(NT-IT)))
j.log(1,Dxc[1690],string.format(Dxc[2248],#GT,tT,M.fmt(NT-IT),db.level(rT.collection:get_unit_by_uuid(I.fuseXpUnit)or sT)))
elseif#GT>20 then
P.fuseBatch=20
j.log(1,Dxc[1690],string.format(Dxc[2249],#GT,tostring(j.gameSaid(JT)or(KT and LT)or Dxc[1771])))
else
local QT=j.gameSaid(JT)
P.pickNote.autoFuseXp=Dxc[2250]..tostring(QT or(KT and LT)or Dxc[1771])..Dxc[2251]
j.log(1,Dxc[1690],Dxc[2252]..tostring(QT or(KT and LT)or Dxc[1771]))
j.backoff(Dxc[2243],1800)
