if not DV.farm and not DV.train and DV.cost>0 then
BV=math.max(BV,DV.gain/DV.cost)
end
end
for EV,FV in ipairs(wV)do
if FV.train==Dxc[2323]or(FV.train==Dxc[2324]and AV)then
FV.gain=math.max(FV.gain,BV*FV.cost*1.05)
end
end
end
