function Q.buildPath()
Q.samples={}
local vDb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not vDb then
return
end
for wDb,xDb in pairs(vDb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[wDb.Name])then
local yDb={}
for zDb,ADb in ipairs(xDb.points or{})do
table.insert(yDb,ADb.part.Position)
end
local BDb=0
for CDb=2,#yDb do
BDb=BDb+(yDb[CDb]-yDb[CDb-1]).Magnitude
end
local DDb=0
for EDb=2,#yDb do
local FDb,GDb=yDb[EDb-1],yDb[EDb]
local HDb=(GDb-FDb).Magnitude
local IDb=math.max(1,math.floor(HDb/2))
for JDb=0,IDb-1 do
local KDb=FDb:Lerp(GDb,JDb/IDb)
table.insert(Q.samples,{pos=KDb,prog=(DDb+HDb*JDb/IDb)/math.max(1,BDb),lane=wDb.Name})
end
DDb=DDb+HDb
end
if yDb[#yDb]then
table.insert(Q.samples,{pos=yDb[#yDb],prog=1,lane=wDb.Name})
end
end
end
Q.laneCut,Q.laneWant,Q.laneFirst=nil,nil,nil
local LDb=tonumber(Q.ld and Q.ld._portal_lanes)
local MDb=W.laneList(Q.samples)
if LDb and LDb>=1 and MDb and#MDb>LDb then
