function Q.infStop(uEb)
local vEb=0
for wEb,xEb in ipairs(M.list(H.GS.DAILY_INFINITE_REWARDS))do
vEb=math.max(vEb,tonumber(xEb.wave)or 0)
end
if vEb<=0 or uEb<=vEb+1 then
return
end
local yEb=J.train.on
if Q.trainee and yEb and yEb.have+(yEb.got or 0)+(Q.trainTk or 0)<yEb.need then
