return true
end
local mGb=J.blocked[Q.mapKey()]
return mGb and(tonumber(mGb[lGb])or 0)>=2
end
function Q.valid(nGb,oGb)
local pGb=H.PC.raycast(nGb+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not pGb then
return nil
end
if not H.PC.is_valid_raycast_hit(pGb.Instance,oGb)then
