for sGb,tGb in ipairs(Q.mine or{})do
local uGb=tGb:FindFirstChild(Dxc[2956])
local vGb=uGb and uGb.Position or tGb:GetPivot().Position
local wGb=uGb and math.max(uGb.Size.X,uGb.Size.Z)/2 or 1.5
if(M.flat(qGb)-M.flat(vGb)).Magnitude<rGb+wGb then
return nil
end
end
