end
function Q.buildCandidates()
Q.cands={}
local xGb={}
for yGb=1,#Q.samples,3 do
local zGb=Q.samples[yGb]
local AGb=Q.samples[math.min(#Q.samples,yGb+1)]
local BGb=M.flat(AGb.pos-zGb.pos)
if BGb.Magnitude<0.01 then
BGb=Vector3 .new(1,0,0)
end
BGb=BGb.Unit
local CGb=Vector3 .new(-BGb.Z,0,BGb.X)
for DGb,EGb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for FGb,GGb in ipairs({1,-1})do
local HGb=zGb.pos+CGb*EGb*GGb
local IGb=string.format(Dxc[2955],math.floor(HGb.X/1.5),math.floor(HGb.Z/1.5))
if not xGb[IGb]then
xGb[IGb]=true
table.insert(Q.cands,HGb)
end
end
end
end
end
function Q.coverage(JGb,KGb)
local LGb={}
for MGb,NGb in ipairs(JGb)do
local OGb=NGb._stats
if not N.isFarm(OGb.id.Value)and OGb:FindFirstChild(Dxc[1626])then
table.insert(LGb,{p=M.flat(NGb:GetPivot().Position),r=OGb.range.Value*(N.SUMMONER[OGb.id.Value]and N.SUMMONER[OGb.id.Value].reach or 1),air=Q.canAir(NGb)})
end
end
local PGb,QGb=0,0
if#LGb>0 then
for RGb,SGb in ipairs(Q.samples)do
if SGb.prog>QGb then
local TGb=M.flat(SGb.pos)
for UGb,VGb in ipairs(LGb)do
if(TGb-VGb.p).Magnitude<=VGb.r then
if SGb.prog>PGb then
PGb=SGb.prog
end
if VGb.air then
QGb=SGb.prog
break
end
end
end
end
end
end
local WGb,XGb={},Q.laneCount
if XGb and XGb.n>=2 and#LGb>0 then
local YGb={}
for ZGb,_Gb in ipairs(Q.samples)do
local aHb=M.flat(_Gb.pos)
for bHb,cHb in ipairs(LGb)do
if(aHb-cHb.p).Magnitude<=cHb.r then
local dHb=tostring(_Gb.lane)
YGb[dHb]=(YGb[dHb]or 0)+1
if _Gb.prog>(WGb[dHb]or 0)then
WGb[dHb]=_Gb.prog
end
break
end
end
end
local eHb,fHb={},0
for gHb,hHb in pairs(XGb.by)do
eHb[gHb]=(YGb[gHb]or 0)/math.max(1,hHb)
fHb=math.max(fHb,eHb[gHb])
end
Q.laneW={}
for iHb,jHb in pairs(XGb.by)do
Q.laneW[iHb]=(XGb.avg/math.max(1,jHb))*(1+1.5*(fHb>0 and(1-eHb[iHb]/fHb)or 0))
end
Q.laneFrac=eHb
else
Q.laneW,Q.laneFrac=nil,nil
end
local kHb,lHb,mHb
if#LGb>0 then
for nHb,oHb in ipairs(KGb)do
local pHb=(Q.laneW and oHb.lane and WGb[oHb.lane])or PGb
if oHb.hp>0 and oHb.prog>pHb+0.02 and oHb.prog>(kHb or 0)then
kHb,mHb=oHb.prog,Q.laneW and oHb.lane or nil
end
if oHb.hp>0 and oHb.fly and oHb.prog>QGb+0.02 then
lHb=true
end
end
end
local qHb= #LGb>0 and(Q.pressure or 0)>=PGb-0.08
return{covEnd=PGb,airEnd=QGb,leak=kHb,leakLane=mHb,covL=WGb,airLeak=lHb,push=qHb,units= #LGb}
end
function Q.needLastLine(rHb)
if N.isFarm(rHb.id)or N.allyBuff(rHb.id)or Q.fieldCount()<5 then
return false
end
local sHb,tHb=0,0
for uHb,vHb in ipairs(Q.mine or{})do
local wHb=vHb._stats
if not N.isFarm(wHb.id.Value)and wHb:FindFirstChild(Dxc[1626])then
local xHb,yHb=M.flat(vHb:GetPivot().Position),wHb.range.Value
for zHb,AHb in ipairs(Q.samples)do
if AHb.prog>=0.85 and(M.flat(AHb.pos)-xHb).Magnitude<=yHb then
sHb=sHb+1
if Q.canAir(vHb)then
tHb=tHb+1
end
break
