return sHb<2 or(tHb<1 and Q.flyMode()and Q.cardAir(rHb.id))
end
Q.airCache=setmetatable({},{__mode=Dxc[1672]})
function Q.canAir(BHb)
local CHb=BHb._stats:FindFirstChild(Dxc[1575])and BHb._stats.upgrade.Value or 0
local DHb=Q.airCache[BHb]
if not DHb or DHb.lvl~=CHb then
local EHb=BHb:GetAttribute(Dxc[2957])==true or BHb:GetAttribute(Dxc[2958])==true
DHb={lvl=CHb,v=EHb}
Q.airCache[BHb]=DHb
