N._airFrom={}
function N.airFrom(FHb)
local GHb=N._airFrom[FHb]
if GHb~=nil then
return GHb or nil
end
local HHb=H.Units[FHb]
if HHb and(HHb.hill_unit or HHb.hybrid_placement or N.SUMMONER[FHb])then
N._airFrom[FHb]=0
