end
local IHb=N.rows(FHb)
if not(IHb and IHb.max)then
return Q.cardAir(FHb)and 0 or nil
end
local JHb=false
for KHb=0,IHb.max do
local LHb=IHb[KHb]and IHb[KHb].atk
if LHb and H.Attacks[LHb]and H.Attacks[LHb].targets_flying then
JHb=KHb
break
end
end
if JHb==false and Q.cardAir(FHb)then
JHb=0
end
N._airFrom[FHb]=JHb
return JHb or nil
end
function Q.cardAir(MHb)
