end
function Q.airShare()
local PHb,QHb=0,0
for RHb,SHb in ipairs(Q.mine or{})do
local THb=SHb._stats.id.Value
if not N.isFarm(THb)then
local UHb,VHb=pcall(Q.liveDps,SHb,THb)
VHb=UHb and VHb or 0
PHb=PHb+VHb
if Q.canAir(SHb)then
QHb=QHb+VHb
end
end
end
return PHb>0 and QHb/PHb or 0
end
function Q.cover(WHb,XHb,YHb,ZHb)
