for dIb,eIb in ipairs(Q.samples)do
if(M.flat(eIb.pos)-aIb).Magnitude<=XHb then
local fIb=1
if bIb then
fIb=0.15+0.85*(tonumber(bIb[math.min(W.BINS,math.floor(eIb.prog*W.BINS)+1)])or 0)
end
if cIb then
fIb=fIb*(cIb[tostring(eIb.lane)]or 1)
end
if ZHb then
if ZHb.leak and eIb.prog>=ZHb.leak-0.01 and(not ZHb.leakLane or tostring(eIb.lane)==ZHb.leakLane)then
fIb=fIb+3
elseif ZHb.push and eIb.prog>ZHb.covEnd then
fIb=fIb+0.6
end
end
_Hb=_Hb+fIb
end
end
