if(M.flat(nNb.pos)-jNb).Magnitude<=fNb then
lNb=lNb+1
if math.abs(nNb.prog-eNb)<=0.05 then
kNb=kNb+1
local oNb=M.flat(nNb.pos)
for pNb,qNb in ipairs(VMb)do
if(oNb-qNb.p).Magnitude<=qNb.r then
kNb=kNb-0.5
break
end
end
end
end
end
if kNb>0 then
table.insert(gNb,{pos=iNb,sc=kNb,cov=lNb})
