if JQb<FQb then
FQb,GQb=JQb,IQb.pos
end
end
local KQb=GQb and M.flat(GQb-EQb)or Vector3 .new(0,0,-1)
return KQb.Magnitude>0.01 and KQb.Unit or Vector3 .new(0,0,-1)
end
function Q.place(LQb,MQb)
local NQb=N.isFarm(LQb.id)
local OQb,PQb=Q.bestSpot(LQb,NQb or(Q.random and N.idol(LQb.id)),(Q.trainee~=nil and LQb.uuid==Q.trainee)or N.ENTRY[LQb.id]==true or(Q.studyEntry==true and LQb.id==Q.trialId))
if not OQb then
Q.noSpot[LQb.uuid]=(Q.noSpot[LQb.uuid]or 0)+1
j.status(Dxc[2995],Dxc[3005]..N.name(LQb.id))
