end
local QQb=Q.money()
local RQb,SQb=j.request(Dxc[3006],Dxc[3007],LQb.uuid,H.Util.CFramePLV(OQb,Q.lookAt(OQb)))
if RQb and SQb then
Q.spent=Q.spent+(LQb.data.cost or 0)
table.insert(Q.actions,string.format(Dxc[3008],N.name(LQb.id)))
j.log(1,Dxc[3000],string.format(Dxc[3009],N.name(LQb.id),Q.spotKey(OQb),PQb,MQb))
Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=LQb.id,x=math.floor(OQb.X),z=math.floor(OQb.Z),cover=math.floor((PQb or 0)+0.5),why=tostring(MQb):sub(1,90)})
j.status(Dxc[2995],string.format(Dxc[3010],N.name(LQb.id),MQb))
Q.placedAt=Q.placedAt or{}
Q.placedAt[LQb.uuid]=(Q.placedAt[LQb.uuid]or 0)+1
return true
end
if QQb>=(LQb.data.cost or 0)and Q.random then
Q.placeFail=Q.placeFail or{}
Q.placeFail[LQb.uuid]=(Q.placeFail[LQb.uuid]or 0)+1
if Q.placeFail[LQb.uuid]>=2 then
Q.noSpot[LQb.uuid]=3
j.log(1,Dxc[3000],string.format(Dxc[3011],N.name(LQb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if RQb and QQb>=(LQb.data.cost or 0)and not Q.random then
local TQb=Q.spotKey(OQb)
Q.refused[TQb]=true
local UQb=Q.mapKey()
J.blocked[UQb]=J.blocked[UQb]or{}
if not Q.refusedRun[TQb]then
J.blocked[UQb][TQb]=(tonumber(J.blocked[UQb][TQb])or 0)+1
Q.refusedRun[TQb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[LQb.uuid]=(Q.unitRefusals[LQb.uuid]or 0)+1
if Q.unitRefusals[LQb.uuid]>=3 then
local VQb=math.max(1,Q.count(LQb.uuid))
if J.caps[LQb.uuid]~=VQb then
