j.log(1,Dxc[3000],string.format(Dxc[3012],N.name(LQb.id),VQb))
end
end
j.log(2,Dxc[3000],Dxc[3013]..TQb..Dxc[2036]..N.name(LQb.id))
j.saveSoon()
end
return false
end
function Q.count(WQb)
