for YQb,ZQb in ipairs({workspace._UNITS,workspace:FindFirstChild(Dxc[3014])})do
if ZQb then
for _Qb,aRb in ipairs(ZQb:GetChildren())do
local bRb=aRb:FindFirstChild(Dxc[1548])
if bRb and bRb:FindFirstChild(Dxc[3003])and bRb.player.Value==G and bRb.uuid.Value==WQb then
XQb=XQb+1
