function Q.measure()
local cRb,dRb=Q.calRun,Q.info
if not(cRb and dRb)then
return
end
pcall(Q.sampleHelpers)
local eRb=M.now()
local fRb=Q.wave()
local gRb=Q.money()
if not cRb.start and gRb>0 and#Q.mine==0 then
cRb.start=gRb
end
if fRb~=cRb.lastW then
if Q.trialId and fRb>0 then
Q.trialTrace=Q.trialTrace or{}
local hRb,iRb,jRb,kRb=0,{},0,0
for lRb,mRb in ipairs(Q.mine)do
local nRb=mRb._stats
if nRb.id.Value==Q.trialId then
hRb=hRb+1
table.insert(iRb,tostring(nRb.upgrade.Value))
elseif not N.isFarm(nRb.id.Value)then
kRb=kRb+1
end
end
pcall(Q.sampleHelpers,true)
for oRb,pRb in pairs(Q.ownDealt)do
if pRb.id==Q.trialId then
jRb=jRb+pRb.v
end
end
local qRb=0
for rRb,sRb in pairs(Q.helperDealt)do
if sRb.owner==Q.trialId then
qRb=qRb+sRb.v
end
end
table.insert(Q.trialTrace,string.format(Dxc[3015],fRb,eRb-(Q.startT or eRb),gRb,table.concat(iRb,Dxc[2104]),kRb,jRb+qRb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[fRb-1]or 0,Q.teamDps or 0))
end
if cRb.lastW and cRb.lastW>0 and cRb.lastWT then
table.insert(cRb.waveSec,eRb-cRb.lastWT)
end
if cRb.paidT and fRb>0 and eRb-cRb.paidT<15 then
table.insert(cRb.skip,eRb-cRb.paidT)
end
cRb.paidT=nil
if fRb>0 then
cRb.alive[tostring(fRb)]=Q.hpAliveRaw or 0
end
cRb.lastW,cRb.lastWT=fRb,eRb
end
local tRb=workspace:FindFirstChild(Dxc[3016])
if tRb and fRb>0 then
cRb.timer[tostring(fRb)]=math.max(cRb.timer[tostring(fRb)]or 0,tonumber(tRb.Value)or 0)
end
local uRb=gRb-(Q.lastMoneyR or gRb)
Q.lastMoneyR=gRb
Q.incomeLog=Q.incomeLog or{}
if uRb>0 then
table.insert(Q.incomeLog,{t=eRb,y=uRb})
end
while Q.incomeLog[1]and eRb-Q.incomeLog[1].t>30 do
table.remove(Q.incomeLog,1)
end
local vRb=0
for wRb,xRb in ipairs(Q.incomeLog)do
vRb=vRb+xRb.y
end
local yRb=math.min(30,eRb-(Q.startT or eRb))
Q.incomeRate=yRb>=8 and vRb/yRb or nil
for zRb,ARb in ipairs(Q.enemies)do
local BRb=ARb.m
local CRb=Q.track[BRb]
if not CRb then
local DRb=BRb._stats
local ERb=BRb:FindFirstChildOfClass(Dxc[2943])
local FRb=dRb.cfgById[DRb.id.Value]
local GRb=FRb and W.baseStats(dRb,FRb)
if ERb and GRb and fRb>0 then
local HRb=GRb*dRb.hpRaw*W.waveScale(dRb,fRb,dRb.list[fRb])
if HRb>0 and ERb.MaxHealth>0 then
table.insert(cRb.hp,ERb.MaxHealth/HRb)
end
end
Q.track[BRb]={t=eRb,p=ARb.prog,sp=(DRb:FindFirstChild(Dxc[3017])and tonumber(DRb.speed.Value))or 1}
if fRb>0 then
cRb.spawn[tostring(fRb)]=(cRb.spawn[tostring(fRb)]or 0)+1
cRb.spawnLast[tostring(fRb)]=eRb-(cRb.lastWT or eRb)
end
elseif not CRb.done and eRb-CRb.t>=15 then
CRb.done=true
local IRb=(ARb.prog-CRb.p)/(eRb-CRb.t)/math.max(0.1,CRb.sp)
if IRb>0.001 and ARb.prog<0.95 then
table.insert(cRb.walk,IRb)
end
end
end
local JRb=0
for KRb,LRb in ipairs(Q.mine)do
local MRb=LRb._stats:FindFirstChild(Dxc[3018])
if MRb then
JRb=JRb+MRb.Value
end
end
cRb.potSum=cRb.potSum or 0
if cRb.lastDealtT then
local NRb=eRb-cRb.lastDealtT
local ORb=0
for PRb,QRb in ipairs(Q.mine)do
local RRb=QRb._stats
local SRb=RRb.id.Value
if not N.isFarm(SRb)and RRb:FindFirstChild(Dxc[3019])and RRb.target.Value~=nil then
local TRb,URb=pcall(Q.liveDps,QRb,SRb)
if TRb and URb then
