function fb.evolveOptions(lnc)
local mnc={{text=Dxc[3484],value=Dxc[418]}}
local nnc=H.session()
if not nnc then
return mnc
end
local onc={}
for pnc,qnc in ipairs(N.equipped())do
onc[qnc.uuid]=true
end
local rnc={}
for snc,tnc in pairs(nnc.profile_data.collection.owned_units)do
local unc=H.Units[tnc.unit_id]
if unc and unc.evolve and unc.evolve.evolve_unit and not unc.evolve.hide_from_ui and H.Units[unc.evolve.evolve_unit]then
local vnc=(snc==lnc and 1e9 or 0)+(onc[snc]and 1e6 or 0)+(tonumber(tnc.xp)or 0)
if not rnc[tnc.unit_id]or vnc>rnc[tnc.unit_id].key then
rnc[tnc.unit_id]={uuid=snc,id=tnc.unit_id,to=unc.evolve.evolve_unit,key=vnc}
end
end
end
local wnc={}
for xnc,ync in pairs(rnc)do
table.insert(wnc,ync)
end
table.sort(wnc,function(znc,Anc)
if znc.key~=Anc.key then
return znc.key>Anc.key
end
return znc.uuid<Anc.uuid
end)
for Bnc,Cnc in ipairs(wnc)do
local Dnc=nnc.collection:get_unit_by_uuid(Cnc.uuid)
local Enc,Fnc=pcall(H.USC.calculate_level,Cnc.id,Dnc and Dnc.xp or 0)
table.insert(mnc,{text=string.format(Dxc[3492],N.name(Cnc.id),N.name(Cnc.to),Enc and tonumber(Fnc)or 0,onc[Cnc.uuid]and Dxc[3490]or Dxc[418]),value=Cnc.uuid})
end
return mnc
end
